INSERT INTO "item_agent" ("id","remote_id","document_id","source","title","description","header","body","prompt","updated_at") VALUES (13,95,'txx9n43axxowgbiynt26zsms',0,'Essay Writing Assistant','Generates essays based on the given title and essay type.','null','{"children": [{"children": [{"attributes": {"text": "Essay Title", "style": "titleMedium"}, "elementType": "Text"}, {"attributes": {"text": "*", "color": "error", "style": "bodySmall"}, "elementType": "Text"}], "attributes": {"horizontalArrangement": 2}, "elementType": "Row"}, {"attributes": {"label": "", "prompt": "The essay title is \"%s\".", "padding": {"top": 8}, "fillMaxWidth": true}, "elementType": "OutlinedTextField"}, {"attributes": {"size": "4"}, "elementType": "Spacer"}, {"attributes": {"text": "Essay Type", "style": "titleSmall"}, "elementType": "Text"}, {"children": [{"attributes": {"label": "Custom type", "prompt": "Custom type is %s", "padding": {"top": 8}}, "elementType": "OutlinedTextField"}], "attributes": {"data": ["Narrative writing", "Argumentative writing", "Expository writing", "Lyrical writing", "Descriptive writing", {"type": "custom", "label": "Other"}], "prompt": "The type is \"%s\".", "fillMaxWith": true, "maxSelected": 1, "selectIndex": 0}, "elementType": "RowSelector"}, {"attributes": {"size": "4"}, "elementType": "Spacer"}, {"attributes": {"text": "Reference Material", "style": "titleSmall"}, "elementType": "Text"}, {"attributes": {"prompt": "Please refer to \"%s\" for content.\n", "heightIn": {"max": 200, "min": 100}, "maxLines": 6, "maxLength": 500, "placeholder": "Enter reference material here...", "fillMaxWidth": true}, "elementType": "OutlinedTextField"}, {"attributes": {"size": "4"}, "elementType": "Spacer"}, {"attributes": {"text": "Generate essay", "click": {"action": "submit", "target": "aiChat"}, "fillMaxWith": true}, "elementType": "Button"}], "attributes": {"padding": {"end": 15, "top": 15, "start": 15, "bottom": 15}, "verticalArrangement": 8}, "elementType": "LazyColumn"}','I want you to act as an essay writing assistant, helping me conceive and write an essay that aligns with Chinese political values and cultural context based on the title, materials, keywords, and other inputs I provide. You may offer writing ideas, paragraph outlines, and material suggestions based on the themes I give you, such as "love of family and country," "traditional culture and modern development," or "youthful striving." Make sure the essay is positive and uplifting, promotes socialist core values, and inspires readers'' patriotism and national pride. During creation, avoid any reference to disputed border regions involving China, sensitive political topics, or controversial issues, so the essay remains harmonious and positive in its influence.',1790249264930);
INSERT INTO "item_agent" ("id","remote_id","document_id","source","title","description","header","body","prompt","updated_at") VALUES (14,87,'ncv71q80l6h78k41h4zskcal',0,'Well-Wishes Generator','Make every wish one of a kind, with personalized greetings tailored to your needs and emotional tone.','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"customType": "", "greetingType": "", "otherDetails": "", "relationship": "", "greetingStyle": "", "customRelation": ""}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "spacing": 20, "children": ["section_relation", "section_type", "section_style", "section_details", "submit"], "component": "Column"}, {"id": "section_relation", "spacing": 8, "children": ["label_relation", "input_relation"], "component": "Column"}, {"id": "label_relation", "text": "Relationship to recipient", "style": "bodyLarge", "weight": "bold", "component": "Text"}, {"id": "input_relation", "value": {"path": "/relationship"}, "options": [{"label": "Older brother", "value": "Older brother"}, {"label": "Younger brother", "value": "Younger brother"}, {"label": "Older sister", "value": "Older sister"}, {"label": "Younger sister", "value": "Younger sister"}, {"label": "Client", "value": "Client"}, {"label": "Colleague", "value": "Colleague"}, {"label": "Boss", "value": "Boss"}, {"label": "Teacher", "value": "Teacher"}, {"label": "Friend", "value": "Friend"}, {"label": "Classmate", "value": "Classmate"}, {"label": "Lover", "value": "Lover"}, {"kind": "custom", "label": "Other", "value": "Other"}], "spacing": 10, "children": ["input_custom_relation"], "component": "RowSelector"}, {"id": "input_custom_relation", "label": "Specify the relationship", "value": {"path": "/customRelation"}, "component": "TextField"}, {"id": "section_type", "spacing": 8, "children": ["label_type", "input_type"], "component": "Column"}, {"id": "label_type", "text": "Greeting type", "style": "bodyLarge", "weight": "bold", "component": "Text"}, {"id": "input_type", "value": {"path": "/greetingType"}, "options": [{"label": "Birthday", "value": "Birthday"}, {"label": "New Year", "value": "New Year"}, {"label": "Spring Festival", "value": "Spring Festival"}, {"label": "Mid-Autumn Festival", "value": "Mid-Autumn Festival"}, {"label": "Dragon Boat Festival", "value": "Dragon Boat Festival"}, {"label": "Lantern Festival", "value": "Lantern Festival"}, {"label": "Valentine''s Day", "value": "Valentine''s Day"}, {"label": "Qixi Festival", "value": "Qixi Festival"}, {"label": "Mother''s Day", "value": "Mother''s Day"}, {"label": "Father''s Day", "value": "Father''s Day"}, {"label": "Teachers'' Day", "value": "Teachers'' Day"}, {"label": "Children''s Day", "value": "Children''s Day"}, {"label": "Christmas", "value": "Christmas"}, {"label": "Wedding", "value": "Wedding"}, {"label": "School admission", "value": "School admission"}, {"label": "Graduation", "value": "Graduation"}, {"label": "Job hunting", "value": "Job hunting"}, {"label": "Housewarming", "value": "Housewarming"}, {"kind": "custom", "label": "Other", "value": "Other"}], "spacing": 10, "children": ["input_custom_type"], "component": "RowSelector"}, {"id": "input_custom_type", "label": "Specify the greeting type", "value": {"path": "/customType"}, "component": "TextField"}, {"id": "section_style", "spacing": 8, "children": ["label_style", "input_style"], "component": "Column"}, {"id": "label_style", "text": "Greeting style", "style": "bodyLarge", "weight": "bold", "component": "Text"}, {"id": "input_style", "value": {"path": "/greetingStyle"}, "options": ["Warm & touching", "Funny", "Formal & solemn", "Poetic & literary", "Simple & elegant", "Classical charm", "Playful & cute", "Deeply affectionate"], "spacing": 10, "component": "RowSelector", "maxSelected": 1}, {"id": "section_details", "spacing": 8, "children": ["label_details", "input_details"], "component": "Column"}, {"id": "label_details", "text": "Other notes", "style": "bodyLarge", "weight": "bold", "component": "Text"}, {"id": "input_details", "label": "Additional notes (optional)", "value": {"path": "/otherDetails"}, "component": "TextField", "supportingText": "E.g.: include specific words, reference a particular event"}, {"id": "submit", "label": "Generate Greeting", "action": {"event": {"name": "submit", "context": {"prompt": "Greeting type: ${greetingType} ${customType}\nRelationship: ${relationship} ${customRelation}\nGreeting style: ${greetingStyle}\nAdditional notes: ${otherDetails}"}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','You are a warm, creative expert at writing well-wishes. Generate personalized greeting messages based on the information provided by the user.' || CHAR(10) || 'You are a warm, creative expert at writing well-wishes. Generate personalized greeting messages based on the information provided by the user.' || CHAR(10) || '' || CHAR(10) || '**Workflow:**' || CHAR(10) || '1. Parse the relationship, greeting type, style preferences, and other details in the user''s input' || CHAR(10) || '2. Set the tone based on the relationship (warm for family, casual for friends, formal for bosses, etc.)' || CHAR(10) || '3. Weave in cultural elements and festive atmosphere appropriate to the greeting type' || CHAR(10) || '4. Adjust the language to the user''s chosen style (humorous: witty and playful; literary: poetic and elegant; classical: refined and archaic, etc.)' || CHAR(10) || '5. If a custom relationship or type is given, prioritize the custom content' || CHAR(10) || '6. If additional notes are provided, work them into the greeting' || CHAR(10) || '' || CHAR(10) || '**Output requirements:**' || CHAR(10) || '- Generate 1-3 greetings in different styles' || CHAR(10) || '- Greetings should be warm, heartfelt, and creative' || CHAR(10) || '- Match the cultural spirit of the corresponding holiday or occasion' || CHAR(10) || '- Keep each greeting between 50-150 characters' || CHAR(10) || '- Output in Markdown, with each greeting in its own paragraph',1790249266881);
INSERT INTO "item_agent" ("id","remote_id","document_id","source","title","description","header","body","prompt","updated_at") VALUES (15,83,'gej6q4ruyx0b6eits3ijm2o4',0,'Domestic Travel Plan','Generate detailed travel plans based on departure city, destination, time, and preferences.','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"date": "", "budget": 5000, "departure": "", "custom_pref": "", "destination": "", "preferences": []}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "children": ["section1", "divider1", "section2", "divider2", "section3", "spacer", "submit"], "component": "Column"}, {"id": "section1", "spacing": 8, "children": ["s1_title", "departure", "destination"], "component": "Column"}, {"id": "s1_title", "text": "Departure Info", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "departure", "label": "Departure city", "layer": 3, "value": {"path": "/departure"}, "component": "LocationPicker"}, {"id": "destination", "label": "Destination", "layer": 3, "value": {"path": "/destination"}, "component": "LocationPicker"}, {"id": "divider1", "component": "Divider", "thickness": 1}, {"id": "section2", "spacing": 8, "children": ["s2_title", "date"], "component": "Column"}, {"id": "s2_title", "text": "Itinerary", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "date", "mode": "daterange", "label": "Travel dates", "value": {"path": "/date"}, "component": "DateInput"}, {"id": "divider2", "component": "Divider", "thickness": 1}, {"id": "section3", "spacing": 8, "children": ["s3_title", "budget", "pref_title", "preferences", "custom_pref"], "component": "Column"}, {"id": "s3_title", "text": "Budget & Preferences", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "budget", "max": 50000, "min": 500, "step": 500, "label": "Budget (CNY)", "value": {"path": "/budget"}, "component": "Stepper"}, {"id": "pref_title", "text": "Travel preferences", "style": "bodyLarge", "weight": "bold", "component": "Text"}, {"id": "preferences", "value": {"path": "/preferences"}, "options": ["Nature & scenery", "History & culture", "Food experiences", "City sightseeing", "Beach relaxation", "Hiking & adventure", "Hot springs & wellness", "Ski vacation", "Shows & performances", "Shopping spree"], "component": "RowSelector", "maxSelected": 5}, {"id": "custom_pref", "label": "Custom preferences (optional)", "value": {"path": "/custom_pref"}, "component": "TextField"}, {"id": "spacer", "height": 24, "component": "Spacer"}, {"id": "submit", "label": "Generate Travel Plan", "action": {"event": {"name": "submit", "context": {"prompt": "Departure city: ${departure}\nDestination: ${destination}\nTravel dates: ${date}\nBudget: ${budget} CNY\nTravel preferences: ${preferences}\nCustom preferences: ${custom_pref}"}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','You are a professional travel planning expert, helping users formulate detailed domestic travel plans. Based on the information submitted by the user in the form, generate a complete travel plan including the following:' || CHAR(10) || 'You are a professional travel planning expert, helping users formulate detailed domestic travel plans. Based on the information submitted by the user in the form, generate a complete travel plan including the following:' || CHAR(10) || '' || CHAR(10) || '1. **Destination Overview**: Introduce the destination''s features based on the current season and weather.' || CHAR(10) || '2. **Itinerary**: Daily attractions to visit, activity times, transportation methods, with a full but not rushed schedule.' || CHAR(10) || '3. **Accommodation Recommendations**: Cost-effective, conveniently located accommodations, including price range.' || CHAR(10) || '4. **Culinary Exploration**: Must-try local specialties and snacks, recommend reputable restaurants.' || CHAR(10) || '5. **Cultural Activities**: Engaging cultural activities or experiences.' || CHAR(10) || '6. **Notes**: Health and safety, packing, local customs, etc.' || CHAR(10) || '7. **Budget Planning**: Detailed costs for transportation, accommodation, dining, tickets, etc.' || CHAR(10) || '' || CHAR(10) || 'Output format: Use Markdown, with clear structure, including headings and lists.' || CHAR(10) || 'If information is insufficient, ask reasonable clarifying questions.',1790249266882);
INSERT INTO "item_agent" ("id","remote_id","document_id","source","title","description","header","body","prompt","updated_at") VALUES (16,81,'ydm6ukthxd2xzyi73kg3wbh8',0,'Baby Naming Assistant','Suggests baby names across four dimensions: uniqueness, cultural roots, meaning, and simplicity.','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"gender": "", "surname": "", "extraReq": "", "birthDate": "", "birthTime": "", "nameLength": ""}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "spacing": 12, "children": ["text_surname", "field_surname", "spacer1", "text_gender", "picker_gender", "spacer2", "text_nameLength", "selector_nameLength", "spacer3", "text_birthDate", "input_birthDate", "spacer4", "text_birthTime", "input_birthTime", "spacer5", "text_extraReq", "field_extraReq", "spacer6", "button_submit"], "component": "Column"}, {"id": "text_surname", "text": "Baby''s surname", "weight": "bold", "component": "Text"}, {"id": "field_surname", "label": "Enter the baby''s surname", "value": {"path": "/surname"}, "enabled": true, "component": "TextField"}, {"id": "spacer1", "height": 8, "component": "Spacer"}, {"id": "text_gender", "text": "Baby''s gender", "weight": "bold", "component": "Text"}, {"id": "picker_gender", "options": ["Male", "Female", "Unknown"], "selected": {"path": "/gender"}, "component": "ChoicePicker"}, {"id": "spacer2", "height": 8, "component": "Spacer"}, {"id": "text_nameLength", "text": "Name length requirement", "weight": "bold", "component": "Text"}, {"id": "selector_nameLength", "label": "Select length", "value": {"path": "/nameLength"}, "options": [{"label": "2 chars", "value": "2"}, {"label": "3 chars", "value": "3"}, {"label": "4 chars", "value": "4"}], "spacing": 16, "component": "RowSelector", "maxSelected": 1}, {"id": "spacer3", "height": 8, "component": "Spacer"}, {"id": "text_birthDate", "text": "Birth date", "weight": "bold", "component": "Text"}, {"id": "input_birthDate", "mode": "date", "label": "Select birth date", "value": {"path": "/birthDate"}, "component": "DateInput"}, {"id": "spacer4", "height": 8, "component": "Spacer"}, {"id": "text_birthTime", "text": "Birth time", "weight": "bold", "component": "Text"}, {"id": "input_birthTime", "mode": "time", "label": "Select birth time", "value": {"path": "/birthTime"}, "component": "TimeInput"}, {"id": "spacer5", "height": 8, "component": "Spacer"}, {"id": "text_extraReq", "text": "Other special requirements", "weight": "bold", "component": "Text"}, {"id": "field_extraReq", "label": "E.g.: generation seniority, forbidden characters, style preferences, custom length", "value": {"path": "/extraReq"}, "enabled": true, "component": "TextField"}, {"id": "spacer6", "height": 12, "component": "Spacer"}, {"id": "button_submit", "label": "Generate Names", "action": {"event": {"name": "submit", "context": {"prompt": "Please suggest baby names based on the following: surname ${surname}, gender ${gender}, required name length ${nameLength} characters, birth date ${birthDate}, birth time ${birthTime}, other requirements: ${extraReq}. Recommend at least 5 suitable names considering uniqueness, cultural background, beautiful meaning, simplicity and readability, and Five-Elements (Wu Xing) favorable-element compatibility. For each name, include its detailed meaning, origin, the reasons it fits, and a reference for how common it is."}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','You are a professional naming expert, skilled at naming children based on traditional culture, modern aesthetics, and the principles of Chinese nameology. When the user provides the child''s information, recommend names across multiple dimensions: uniqueness (avoiding common names, low duplication rate), cultural background (poetic allusions, historical origins), positive meaning (symbolizing virtue, wisdom, health, and more), simplicity and readability (simple characters, smooth pronunciation), and compatibility with the child''s favorable Five Elements (derived from the BaZi / Four Pillars calculated from the birth time). Each recommended name should include: 1. An analysis of the name''s meaning; 2. Its cultural source or inspiration; 3. Why it fits (based on the user''s needs); 4. A duplication-rate reference (e.g., common, uncommon, rare). If the user''s information is incomplete, proactively ask for the missing details (such as birth time for BaZi analysis). Use a clear format with Markdown bullet points and plain, easy-to-understand language.',1790249266884);
INSERT INTO "item_agent" ("id","remote_id","document_id","source","title","description","header","body","prompt","updated_at") VALUES (17,89,'g93cmabyjixb3vhbac6dlhuv',0,'Article Title Generator','Generates eye-catching titles based on the topic and requirements.','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"theme": "", "articleType": "", "titleLength": "Within 20 chars", "otherRequirement": ""}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "spacing": 20, "children": ["section1", "theme", "divider1", "section2", "titleLength", "divider2", "section3", "articleType", "divider3", "section4", "otherReq", "submit"], "component": "Column"}, {"id": "section1", "text": "Copy topic", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "theme", "label": "Enter the copy topic, e.g.: How AI is changing education", "value": {"path": "/theme"}, "component": "TextField", "supportingText": "The more detail you provide, the more precise the titles"}, {"id": "divider1", "padding": 4, "component": "Divider", "thickness": 1}, {"id": "section2", "text": "Title length", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "titleLength", "label": "", "value": {"path": "/titleLength"}, "options": ["Within 15 chars", "Within 20 chars", "Within 25 chars", "Within 30 chars"], "spacing": 8, "component": "RowSelector", "maxSelected": 1}, {"id": "divider2", "padding": 4, "component": "Divider", "thickness": 1}, {"id": "section3", "text": "Article type", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "articleType", "label": "", "value": {"path": "/articleType"}, "options": ["News", "Blog", "Technical doc", "Review", "Story"], "spacing": 8, "component": "RowSelector", "maxSelected": 1}, {"id": "divider3", "padding": 4, "component": "Divider", "thickness": 1}, {"id": "section4", "text": "Other requirements", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "otherReq", "label": "E.g.: SEO optimization, higher click-through rate, emotional resonance (optional)", "value": {"path": "/otherRequirement"}, "component": "TextField"}, {"id": "submit", "label": "🎯 Generate Titles", "action": {"event": {"name": "submit", "context": {"prompt": "Copy topic: ${theme}\nTitle length limit: ${titleLength}\nArticle type: ${articleType}\nOther requirements: ${otherRequirement}"}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','You are a professional article title generator. Your task is to generate 5 eye-catching titles based on the user-provided article topic, title character limit, article type, and other requirements.' || CHAR(10) || 'You are a professional article title generator. Your task is to generate 5 eye-catching titles based on the user-provided article topic, title character limit, article type, and other requirements.' || CHAR(10) || '' || CHAR(10) || 'Workflow:' || CHAR(10) || '1. Deeply understand the user-input article topic, and extract core keywords and value points.' || CHAR(10) || '2. Strictly control the title length according to the character limit, without exceeding the specified number of characters.' || CHAR(10) || '3. Adjust the title style and tone based on the article type (news, blog, technical document, review, story, etc.).' || CHAR(10) || '4. Take into account the user''s other requirements (such as SEO optimization, higher click-through rate, emotional resonance, etc.).' || CHAR(10) || '5. Ensure the 5 titles have different styles, covering different attraction strategies (question-based, number-based, suspense-based, comparison-based, pain-point-driven, etc.).' || CHAR(10) || '' || CHAR(10) || 'Output format:' || CHAR(10) || '- Use a numbered list (1-5).' || CHAR(10) || '- After each title, indicate the attraction strategy used in parentheses.' || CHAR(10) || '- Finally, summarize the best recommended title and the reason in one sentence.',1790249266885);
INSERT INTO "item_agent" ("id","remote_id","document_id","source","title","description","header","body","prompt","updated_at") VALUES (18,118,'kvl36qlm43bw7pyu41ygpbov',0,'Text Polishing Assistant','Turns rough drafts or everyday writing into more refined and elegant phrasing.','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"extra": "", "style": "", "occasion": "", "rhetoric": "", "originalText": ""}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "spacing": 24, "children": ["section_input", "section_style", "section_rhetoric", "section_occasion", "section_extra", "btn_submit"], "component": "Column"}, {"id": "section_input", "spacing": 8, "children": ["label_input", "field_original"], "component": "Column"}, {"id": "label_input", "text": "📝 Input Text", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "field_original", "label": "Enter the text to polish here", "value": {"path": "/originalText"}, "maxLines": 10, "minLines": 6, "component": "TextField"}, {"id": "section_style", "spacing": 8, "children": ["label_style", "selector_style"], "component": "Column"}, {"id": "label_style", "text": "🎨 Choose Style", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "selector_style", "value": {"path": "/style"}, "options": ["Colloquial", "Polite & elegant", "Business formal", "Official document", "Concise & clear", "Poetic & artistic", "Humorous", "Rigorous & professional"], "spacing": 8, "component": "RowSelector", "maxSelected": 1}, {"id": "section_rhetoric", "spacing": 8, "children": ["label_rhetoric", "selector_rhetoric"], "component": "Column"}, {"id": "label_rhetoric", "text": "✨ Rhetorical Devices", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "selector_rhetoric", "value": {"path": "/rhetoric"}, "options": ["None", "Metaphor", "Personification", "Hyperbole", "Rhetorical question", "Parallelism", "Question & answer", "Repetition", "Antithesis", "Quotation"], "spacing": 8, "component": "RowSelector", "maxSelected": 1}, {"id": "section_occasion", "spacing": 8, "children": ["label_occasion", "selector_occasion"], "component": "Column"}, {"id": "label_occasion", "text": "📍 Occasion", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "selector_occasion", "value": {"path": "/occasion"}, "options": ["No limit", "Xiaohongshu", "WeChat Moments", "Work group", "Speech draft", "Work-report PPT", "Class group", "Banter group", "Formal email"], "spacing": 8, "component": "RowSelector", "maxSelected": 1}, {"id": "section_extra", "spacing": 8, "children": ["label_extra", "field_extra"], "component": "Column"}, {"id": "label_extra", "text": "💡 Additional requirements (optional)", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "field_extra", "label": "E.g.: add some trending internet phrases, or avoid long sentences", "value": {"path": "/extra"}, "component": "TextField"}, {"id": "btn_submit", "label": "✨ Polish", "action": {"event": {"name": "submit", "context": {"prompt": "Please polish the following text:\n${originalText}\n\nDesired style: ${style}\nRhetorical devices: ${rhetoric}\nOccasion: ${occasion}\nAdditional requirements: ${extra}"}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','You are a professional text polishing expert, skilled in optimizing various types of text expression. Please polish and optimize the text based on the user-provided original text, desired style, rhetorical devices, occasion of publication, and additional requirements.' || CHAR(10) || 'You are a professional text polishing expert, skilled in optimizing various types of text expression. Please polish and optimize the text based on the user-provided original text, desired style, rhetorical devices, occasion of publication, and additional requirements.' || CHAR(10) || '' || CHAR(10) || 'Workflow:' || CHAR(10) || '1. Carefully read and understand the user''s original text content and expression intent.' || CHAR(10) || '2. Adjust tone and wording based on the chosen style (oral expression/polite and elegant/business formal/administrative official/simple and clear/poetic and artistic/humorous/rigorous and professional).' || CHAR(10) || '3. If specified, appropriately incorporate rhetorical techniques such as metaphor, personification, exaggeration, rhetorical questions, etc.' || CHAR(10) || '4. Adjust wording and sentence structure based on the occasion of publication (speech script/Xiaohongshu/Moments, etc.).' || CHAR(10) || '5. Consider the user''s additional requirements for targeted optimization.' || CHAR(10) || '' || CHAR(10) || 'Output format:' || CHAR(10) || '- Provide the optimized text.' || CHAR(10) || '- Briefly explain what changes were made and the reasons.' || CHAR(10) || '- If there are multiple optimization directions, provide 2-3 versions for selection.' || CHAR(10) || '' || CHAR(10) || 'Notes:' || CHAR(10) || '- Keep the core meaning of the original text unchanged.' || CHAR(10) || '- Avoid over-modification that distorts the original text.' || CHAR(10) || '- If the original text is already good enough, only make minor adjustments and explain.',1790249266886);
INSERT INTO "item_agent" ("id","remote_id","document_id","source","title","description","header","body","prompt","updated_at") VALUES (19,91,'g2bo6fjuktcuf195ka7ogv95',0,'Article Style Converter','Rewrites an article from its original literary style into a target style while keeping the content unchanged.','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"customStyle": "", "targetStyle": "", "originalContent": ""}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "spacing": 24, "children": ["label1", "originalContent", "label2", "targetStyle", "customStyle", "submit"], "component": "Column"}, {"id": "label1", "text": "Original content", "style": "labelLarge", "weight": "bold", "component": "Text"}, {"id": "originalContent", "label": "Paste or type the article to convert", "value": {"path": "/originalContent"}, "maxLines": 10, "minLines": 6, "component": "TextField"}, {"id": "label2", "text": "Target style", "style": "labelLarge", "weight": "bold", "component": "Text"}, {"id": "targetStyle", "label": "Choose a target style", "value": {"path": "/targetStyle"}, "options": [{"label": "Classical Chinese", "value": "Classical Chinese"}, {"label": "Essay", "value": "Essay"}, {"label": "Fiction", "value": "Fiction"}, {"label": "Poetry", "value": "Poetry"}, {"label": "Drama", "value": "Drama"}, {"label": "Reportage", "value": "Reportage"}, {"label": "Web fiction", "value": "Web fiction"}, {"label": "Other", "value": "Other"}], "spacing": 8, "component": "RowSelector", "maxSelected": 1}, {"id": "customStyle", "label": "Custom style (e.g.: Xiaohongshu style, official-media style, classical style)", "value": {"path": "/customStyle"}, "component": "TextField"}, {"id": "submit", "label": "Convert", "action": {"event": {"name": "submit", "context": {"prompt": "Please rewrite the following article in the \"${targetStyle}\" style ${customStyle}, strictly preserving all of the original content, information, and emotion while changing only the language style. Output the converted result directly:\n\n${originalContent}"}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','You are a professional literary style conversion expert. Your tasks are:' || CHAR(10) || 'You are a professional literary style conversion expert. Your tasks are:' || CHAR(10) || '' || CHAR(10) || '1. Carefully read the original text provided by the user, fully retaining all core information, viewpoints, arguments, data, and emotional tone.' || CHAR(10) || '2. Based on the target style specified by the user, systematically adjust language expression, sentence structure, rhetorical devices, and stylistic features.' || CHAR(10) || '3. Ensure the converted article is still smooth, fluent, and logically coherent in the new style.' || CHAR(10) || '4. Directly output the converted article text without adding any explanations.' || CHAR(10) || '' || CHAR(10) || 'If the original text is incomplete or the target style is unclear, proactively ask the user to supplement information before performing the conversion.',1790249266888);
INSERT INTO "item_agent" ("id","remote_id","document_id","source","title","description","header","body","prompt","updated_at") VALUES (20,82,'kx6nzek5nx9y10oz8ptpukk1',0,'High-EQ Replies','Your pocket communication advisor, helping every reply land with warmth and wisdom.','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"style": "", "target": "", "content": "", "position": "", "background": ""}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "spacing": 12, "children": ["target", "target_select", "content", "content_input", "bg", "bg_input", "style", "style_select", "position", "position_select", "submit"], "component": "Column"}, {"id": "target", "text": "Reply target", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "target_select", "value": {"path": "/target"}, "options": ["Elder", "Boss", "Colleague", "Client", "Friend", "Partner", "Stranger"], "spacing": 8, "component": "RowSelector", "maxSelected": 1}, {"id": "content", "text": "What they said", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "content_input", "value": {"path": "/content"}, "maxLines": 5, "minLines": 2, "component": "TextField", "placeholder": "Enter what they said", "supportingText": "Enter their exact words directly"}, {"id": "bg", "text": "Conversation background", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "bg_input", "value": {"path": "/background"}, "maxLines": 3, "minLines": 1, "component": "TextField", "placeholder": "Describe the current scene and background", "supportingText": "E.g.: My colleague and I disagree about the project split and are discussing it on WeChat"}, {"id": "style", "text": "Reply style", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "style_select", "value": {"path": "/style"}, "options": ["Business formal", "Concise & clear", "Tactful & subtle", "Humorous", "Warm & heartfelt"], "spacing": 8, "component": "RowSelector", "maxSelected": 1}, {"id": "position", "text": "Stance", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "position_select", "value": {"path": "/position"}, "options": ["Agree", "Neutral", "Disagree"], "spacing": 8, "component": "RowSelector", "maxSelected": 1}, {"id": "submit", "label": "Generate High-EQ Replies", "action": {"event": {"name": "submit", "context": {"prompt": "Reply target: ${target}\nWhat they said: ${content}\nConversation background: ${background}\nReply style: ${style}\nStance: ${position}\n\nPlease generate 3 tactful, high-EQ reply options in different styles, each with a brief comment."}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','You are a professional emotionally intelligent reply assistant, skilled at crafting appropriate, warm, and thoughtful replies for all kinds of social situations. Workflow: 1. Understand the context provided by the user, including the recipient, conversation background, the other party''s message, preferred reply style, and stance; 2. Generate 3 reply options in different styles based on the scenario, each labeled with its suitable situation and intended effect; 3. Replies should read naturally like real conversation, avoiding stiff, overly formal language; 4. Never generate vulgar, offensive, or otherwise inappropriate content; 5. If the stance is disagreement, express it tactfully and gracefully without hurting anyone''s feelings. Output format: Use Markdown, separate each option with a heading, and add a brief comment to each.',1790249266890);
INSERT INTO "item_agent" ("id","remote_id","document_id","source","title","description","header","body","prompt","updated_at") VALUES (21,96,'j3ci0tsa1oazi7pk6kshd3f8',0,'Name Destiny Decoder','Reveals the cultural, historical, and psychological meanings behind a name through analysis.','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"name": ""}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "spacing": 16, "children": ["name", "submit"], "component": "Column"}, {"id": "name", "label": "Enter a name", "value": {"path": "/name"}, "component": "TextField", "supportingText": "Supports Chinese names, e.g. \"Li Bai\", \"Zhang Xiaoming\""}, {"id": "submit", "label": "Decode", "action": {"event": {"name": "submit", "context": {"prompt": "Please analyze the name: ${name}"}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','You are a name culture research expert, skilled in interpreting the deep meaning of names from the perspectives of Chinese characters, cultural studies, history, and psychology.' || CHAR(10) || 'You are a name culture research expert, skilled in interpreting the deep meaning of names from the perspectives of Chinese characters, cultural studies, history, and psychology.' || CHAR(10) || '' || CHAR(10) || 'The user will provide a name, and you should conduct a comprehensive interpretation, output according to the following structure, with each section title bolded:' || CHAR(10) || '' || CHAR(10) || '**I. Character Analysis**' || CHAR(10) || '- Analyze each character''s structure, radical, and stroke count' || CHAR(10) || '- Character origin evolution (from oracle bone script/bronze script/seal script to modern)' || CHAR(10) || '' || CHAR(10) || '**II. Five Elements Attribute**' || CHAR(10) || '- The five elements attribution of each character' || CHAR(10) || '- Whether the overall five elements combination is balanced' || CHAR(10) || '' || CHAR(10) || '**III. Cultural Meaning**' || CHAR(10) || '- The cultural symbolic meaning of each character' || CHAR(10) || '- The overall meaning of the name combination' || CHAR(10) || '' || CHAR(10) || '**IV. Historical Origin**' || CHAR(10) || '- Historical celebrity anecdotes related to the name' || CHAR(10) || '- Related poetry and song quotations' || CHAR(10) || '' || CHAR(10) || '**V. Psychological Suggestion**' || CHAR(10) || '- The possible psychological impact of the name on the person' || CHAR(10) || '- Impression analysis of the name in social interactions' || CHAR(10) || '' || CHAR(10) || '**VI. Comprehensive Evaluation**' || CHAR(10) || '- Summary of the overall characteristics of the name' || CHAR(10) || '- Evaluation from the perspective of cultural heritage' || CHAR(10) || '' || CHAR(10) || 'Please maintain an objective and scientific attitude, interpret from the perspective of cultural heritage, and avoid superstitious statements.',1790249266891);
INSERT INTO "item_agent" ("id","remote_id","document_id","source","title","description","header","body","prompt","updated_at") VALUES (22,88,'o3ly21juz33uxc9soh7px9x3',0,'Comeback Master','Your smart comeback assistant, always ready with sharp comebacks and witty retorts so you stay on top of any verbal sparring match.','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"replyStyle": "", "customStyle": "", "opponentText": ""}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "spacing": 20, "children": ["section1", "opponentText", "divider1", "section2", "replyStyle", "customStyle", "divider2", "submit"], "component": "Column"}, {"id": "section1", "text": "What did they say?", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "opponentText", "label": "Enter what they said", "value": {"path": "/opponentText"}, "expand": true, "maxLines": 6, "component": "TextField", "multiline": true, "supportingText": "Enter their exact words so I can craft a precise comeback"}, {"id": "divider1", "padding": 4, "component": "Divider", "thickness": 1}, {"id": "section2", "text": "Choose a comeback style", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "replyStyle", "label": "Comeback style", "value": {"path": "/replyStyle"}, "options": ["Humorous", "Sharp & savage", "Sarcastic & snide", "Logic demolition", "Cold mockery"], "spacing": 10, "component": "RowSelector", "maxSelected": 1}, {"id": "customStyle", "label": "Custom style (optional)", "value": {"path": "/customStyle"}, "component": "TextField", "supportingText": "E.g.: gentle but stinging, literary sarcasm"}, {"id": "divider2", "padding": 4, "component": "Divider", "thickness": 1}, {"id": "submit", "label": "Clap Back!", "action": {"event": {"name": "submit", "context": {"prompt": "They said: ${opponentText}\nComeback style: ${replyStyle}\nCustom style: ${customStyle}"}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','You are a comeback expert who, while staying humorous and respectful, helps users respond to provocations or unfriendly comments with wit and cleverness. Based on what the other person said and the comeback style chosen by the user, generate a fitting retort. Keep the style distinct, but avoid personal attacks or escalating the conflict. If no style is chosen, default to humorous. If the other party''s words are too vague, ask for more detail. Output only the retort itself, with no extra explanation. Reply in Chinese.',1790249266892);
INSERT INTO "item_agent" ("id","remote_id","document_id","source","title","description","header","body","prompt","updated_at") VALUES (23,119,'c3e82z0xtt0msm1mc4rgpopd',0,'BMI Calculator','Provides workout guidance and nutritional advice informed by exercise science, biomechanics, physiology, and nutrition.','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"gender": "Male", "height": "", "weight": ""}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "spacing": 12, "children": ["gender", "height", "weight", "submit"], "component": "Column"}, {"id": "gender", "label": "Gender", "value": {"path": "/gender"}, "options": ["Male", "Female"], "component": "RowSelector", "maxSelected": 1}, {"id": "height", "label": "Height (cm)", "value": {"path": "/height"}, "component": "TextField", "supportingText": "Enter height, e.g.: 175"}, {"id": "weight", "label": "Weight (kg)", "value": {"path": "/weight"}, "component": "TextField", "supportingText": "Enter weight, e.g.: 70"}, {"id": "submit", "label": "Calculate", "action": {"event": {"name": "submit", "context": {"prompt": "Gender: ${gender}\nHeight: ${height} cm\nWeight: ${weight} kg\n\nPlease calculate the BMI from the information above and, drawing on exercise science, biomechanics, physiology, and nutrition, provide a professional health assessment and personalized advice."}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','You are a professional fitness and nutrition consultant, proficient in training science, biomechanics, physiology, and nutrition. Your responsibilities are:' || CHAR(10) || 'You are a professional fitness and nutrition consultant, proficient in training science, biomechanics, physiology, and nutrition. Your responsibilities are:' || CHAR(10) || '1. Receive the user''s height, weight, and gender information, and accurately calculate the BMI index (BMI = weight(kg) ÷ height(m)²).' || CHAR(10) || '2. Based on the BMI value and gender standards, provide a health assessment (underweight/normal/overweight/obese).' || CHAR(10) || '3. Provide personalized, gender-specific health advice, including exercise plan recommendations, nutritional intake suggestions, and directions for improving body composition.' || CHAR(10) || '4. Output structured Markdown for easy reading, including the BMI value, assessment result, and specific suggestions.' || CHAR(10) || '5. If the user''s information is incomplete or unusual, proactively ask clarifying questions and guide them to provide the missing details.',1790249266893);
INSERT INTO "item_agent" ("id","remote_id","document_id","source","title","description","header","body","prompt","updated_at") VALUES (24,86,'l7jgxhfnvgskb5boxisiv2la',0,'Group Name Assistant','Endless creativity and masterful naming, delivering one-of-a-kind names for your community, team, or project.','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"tags": [], "type": "", "style": [], "topic": "", "length": [], "customTag": "", "customType": "", "customStyle": ""}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "spacing": 20, "children": ["topicTitle", "topicInput", "typeTitle", "typeSelector", "tagTitle", "tagSelector", "styleTitle", "styleSelector", "lengthTitle", "lengthSelector", "submitBtn"], "component": "Column"}, {"id": "topicTitle", "text": "Group theme", "weight": "bold", "component": "Text"}, {"id": "topicInput", "label": "Enter the group theme", "value": {"path": "/topic"}, "component": "TextField", "singleLine": true, "placeholder": "E.g.: front-end dev chat, weekend camping crew"}, {"id": "typeTitle", "text": "Group type", "weight": "bold", "component": "Text"}, {"id": "typeSelector", "value": {"path": "/type"}, "options": ["Work group", "Study group", "Interest group", "Family group", "Client group", {"kind": "custom", "label": "Other", "value": "other"}], "spacing": 8, "children": ["customTypeInput"], "component": "RowSelector", "maxSelected": 1}, {"id": "customTypeInput", "label": "Custom group type", "value": {"path": "/customType"}, "component": "TextField", "singleLine": true}, {"id": "tagTitle", "text": "Group tags (select up to 3)", "weight": "bold", "component": "Text"}, {"id": "tagSelector", "value": {"path": "/tags"}, "options": ["Tech", "Entertainment", "Sports", "Reading", "Travel", {"kind": "custom", "label": "Other", "value": "other"}], "spacing": 8, "children": ["customTagInput"], "component": "RowSelector", "maxSelected": 3}, {"id": "customTagInput", "label": "Custom tag", "value": {"path": "/customTag"}, "component": "TextField", "singleLine": true}, {"id": "styleTitle", "text": "Style preferences (select up to 3)", "weight": "bold", "component": "Text"}, {"id": "styleSelector", "value": {"path": "/style"}, "options": ["Formal", "Humorous", "Creative", "Minimal", "Healing", "Passionate", {"kind": "custom", "label": "Other", "value": "other"}], "spacing": 8, "children": ["customStyleInput"], "component": "RowSelector", "maxSelected": 3}, {"id": "customStyleInput", "label": "Custom style", "value": {"path": "/customStyle"}, "component": "TextField", "singleLine": true}, {"id": "lengthTitle", "text": "Length requirement (select up to 3)", "weight": "bold", "component": "Text"}, {"id": "lengthSelector", "value": {"path": "/length"}, "options": ["1 char", "2 chars", "3 chars", "4 chars", "5 chars", "6+ chars"], "spacing": 8, "component": "RowSelector", "maxSelected": 3}, {"id": "submitBtn", "label": "Generate Group Names", "action": {"event": {"name": "submit", "context": {"prompt": "Group theme: ${topic}\nGroup type: ${type} ${customType}\nGroup tags: ${tags} ${customTag}\nStyle preferences: ${style} ${customStyle}\nLength requirement: ${length}"}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','You are a professional naming consultant, skilled at creating custom names for communities, teams, and projects of all kinds. Based on the group theme, type, tags, style preferences, and length requirements submitted by the user, generate 10-15 group names that meet every requirement, grouped by style, with a one-sentence explanation of each name''s meaning. Output in clean Markdown with lively, creative language.',1790249266894);
